import{_ as r,J as s,b as o,e as n,a8 as l,f as i,L as p}from"./chunks/framework.BXWQBDlf.js";const _=JSON.parse('{"title":"GR32_Resamplers","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Resamplers","entity":"GR32_Resamplers","kind":"Unit","summary":"Provides bitmap resampling, spatial interpolation kernels, super-sampling, discrete convolution, morphological filters, and block transfers.","title":"GR32_Resamplers","date":1789480950000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Resamplers/index.md","filePath":"api/GR32_Resamplers/index.md","lastUpdated":1789480950000,"timestamp":1789480950000,"datetime":"2026-09-15T14:02:30.000Z"}'),c={name:"api/GR32_Resamplers/index.md"};function t(d,e,m,R,T,f){const a=s("ApiMembers");return o(),n("div",null,[e[0]||(e[0]=l('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32_Resamplers</code> unit implements high-performance image resampling, spatial filtering, neighborhood sampling, and block transfer operations in Graphics32.</p><p>It includes:</p><ul><li><strong>Resamplers</strong>: Fast nearest-neighbor (<a href="/api/GR32_Resamplers/TNearestResampler/"><code>TNearestResampler</code></a>), bilinear (<a href="/api/GR32_Resamplers/TLinearResampler/"><code>TLinearResampler</code></a>), draft downscaling (<a href="/api/GR32_Resamplers/TDraftResampler/"><code>TDraftResampler</code></a>), and high-quality arbitrary kernel resampling (<a href="/api/GR32_Resamplers/TKernelResampler/"><code>TKernelResampler</code></a>).</li><li><strong>Spatial Reconstruction Kernels</strong>: A comprehensive collection of filter kernels including Box (<a href="/api/GR32_Resamplers/TBoxKernel/"><code>TBoxKernel</code></a>), Triangle/Linear (<a href="/api/GR32_Resamplers/TLinearKernel/"><code>TLinearKernel</code></a>), Cosine (<a href="/api/GR32_Resamplers/TCosineKernel/"><code>TCosineKernel</code></a>), B-Spline (<a href="/api/GR32_Resamplers/TSplineKernel/"><code>TSplineKernel</code></a>), Mitchell-Netravali (<a href="/api/GR32_Resamplers/TMitchellKernel/"><code>TMitchellKernel</code></a>), Keys Cubic (<a href="/api/GR32_Resamplers/TCubicKernel/"><code>TCubicKernel</code></a>), Hermite (<a href="/api/GR32_Resamplers/THermiteKernel/"><code>THermiteKernel</code></a>), Sinsh (<a href="/api/GR32_Resamplers/TSinshKernel/"><code>TSinshKernel</code></a>), Gaussian (<a href="/api/GR32_Resamplers/TGaussianKernel/"><code>TGaussianKernel</code></a>), and Windowed-Sinc kernels (<a href="/api/GR32_Resamplers/TAlbrechtKernel/"><code>TAlbrechtKernel</code></a>, <a href="/api/GR32_Resamplers/TLanczosKernel/"><code>TLanczosKernel</code></a>, <a href="/api/GR32_Resamplers/TBlackmanKernel/"><code>TBlackmanKernel</code></a>, <a href="/api/GR32_Resamplers/THannKernel/"><code>THannKernel</code></a>, <a href="/api/GR32_Resamplers/THammingKernel/"><code>THammingKernel</code></a>).</li><li><strong>Nested Samplers &amp; Coordinate Transformers</strong>: Sampler chaining via <a href="/api/GR32_Resamplers/TNestedSampler/"><code>TNestedSampler</code></a>, coordinate transformation via <a href="/api/GR32_Resamplers/TTransformer/"><code>TTransformer</code></a>, uniform <a href="/api/GR32_Resamplers/TSuperSampler/"><code>TSuperSampler</code></a>, and recursive adaptive <a href="/api/GR32_Resamplers/TAdaptiveSuperSampler/"><code>TAdaptiveSuperSampler</code></a>.</li><li><strong>Neighborhood &amp; Morphological Samplers</strong>: Discrete convolution (<a href="/api/GR32_Resamplers/TConvolver/"><code>TConvolver</code></a>), bilateral/selective convolution (<a href="/api/GR32_Resamplers/TSelectiveConvolver/"><code>TSelectiveConvolver</code></a>), morphological dilation (<a href="/api/GR32_Resamplers/TDilater/"><code>TDilater</code></a>), erosion (<a href="/api/GR32_Resamplers/TEroder/"><code>TEroder</code></a>), expansion (<a href="/api/GR32_Resamplers/TExpander/"><code>TExpander</code></a>), and contraction (<a href="/api/GR32_Resamplers/TContracter/"><code>TContracter</code></a>).</li><li><strong>Block Transfer Functions</strong>: High-performance unscaled (<a href="/api/GR32_Resamplers/BlockTransfer"><code>BlockTransfer</code></a>, <a href="/api/GR32_Resamplers/BlockTransfer"><code>BlockTransferX</code></a>, <a href="/api/GR32_Resamplers/BlendTransfer"><code>BlendTransfer</code></a>) and scaled (<a href="/api/GR32_Resamplers/StretchTransfer"><code>StretchTransfer</code></a>) bitmap transfer routines.</li></ul>',4)),i("p",null,[p(a,{type:"members"})])])}const G=r(c,[["render",t]]);export{_ as __pageData,G as default};
